/* Omer games – service worker for one app (generated by tools/new-game-pwa.py; do not edit by hand).
   Cache-first for this app's files, versioned cache name so updates roll out; page navigations are
   served from cache and refreshed in the background. Only deletes its own old caches. */
const APP = 'brain';
const VERSION = '825091e7c0';
const PREFIX = 'omer-' + APP + '-';
const CACHE = PREFIX + VERSION;
const FILES = [
  "./",
  "icons/apple-touch-icon.png",
  "icons/icon-192.png",
  "icons/icon-512.png",
  "icons/icon-maskable-512.png",
  "index.html",
  "manifest.webmanifest",
  "pwa.js",
  "../shared/parental.js"
];
const SHARED = new Set(FILES.map(f => new URL(f, self.registration.scope).pathname).filter(p => !(location.origin + p).startsWith(self.registration.scope)));

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' })))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith(PREFIX) && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const shared = SHARED.has(url.pathname); // site-wide files (e.g. ../shared/parental.js) outside this scope
  if (url.origin !== location.origin || (!url.href.startsWith(self.registration.scope) && !shared)) return;
  if (req.mode === 'navigate') {
    // folder URL -> its index.html; ignore ?install=1 etc.
    const page = url.pathname.endsWith('/') ? url.pathname + 'index.html' : url.pathname;
    e.respondWith(caches.open(CACHE).then(async c => {
      const hit = await c.match(page, { ignoreSearch: true });
      const net = fetch(req).then(r => { if (r.ok) c.put(page, r.clone()); return r; }).catch(() => null);
      if (hit) { e.waitUntil(net); return hit; }
      return (await net) || (await c.match(new URL('index.html', self.registration.scope).pathname)) || Response.error();
    }));
    return;
  }
  e.respondWith(caches.open(CACHE).then(async c => {
    const hit = await c.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const r = await fetch(req);
    if (r.ok) c.put(req, r.clone());
    return r;
  }));
});
